import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

/**
 * UI-01: contract for the procedural 9-slice chrome kit.
 *
 * The kit is generated by `scripts/generate_ui_assets.py` and shipped as PNGs
 * under `public/assets/ui/`. JSDOM does not paint `border-image`, so this gate
 * checks the two things a browser pass would otherwise have to catch by eye:
 * the CSS points at real files, and every fill clears AA for the 11 px text
 * that actually sits on it.
 */
const COMPONENT_DIR = dirname(fileURLToPath(import.meta.url));
const CSS = readFileSync(resolve(COMPONENT_DIR, '../index.css'), 'utf8');
const UI_DIR = resolve(COMPONENT_DIR, '../../public/assets/ui');
const LOCK_PATH = resolve(COMPONENT_DIR, '../../../../scripts/assets/ui.lock.json');

interface FrameEntry {
  file: string;
  width: number;
  height: number;
  slice: number;
  borderWidthPx: number;
  ringMinAlpha: number;
  edgeStdMax: number;
  pixelSha256: string;
}

interface FillEntry {
  file: string;
  width: number;
  height: number;
  tile: true;
  p1Rgb: [number, number, number];
  p99Rgb: [number, number, number];
  meanRgb: [number, number, number];
  edgeDiff: number;
  pixelSha256: string;
}

interface Lock {
  version: number;
  assets: Record<string, FrameEntry | FillEntry>;
}

const LOCK = JSON.parse(readFileSync(LOCK_PATH, 'utf8')) as Lock;

function rule(selector: string): string {
  const index = CSS.indexOf(selector);
  expect(index, `missing CSS selector ${selector}`).toBeGreaterThan(-1);
  const start = CSS.indexOf('{', index);
  const end = CSS.indexOf('}', start);
  return CSS.slice(start + 1, end);
}

function source(name: string): string {
  return readFileSync(resolve(COMPONENT_DIR, name), 'utf8');
}

function pngSize(path: string): { width: number; height: number } {
  const bytes = readFileSync(path);
  expect(bytes.subarray(0, 8).toString('hex')).toBe('89504e470d0a1a0a');
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20) };
}

function linear(channel: number): number {
  const value = channel / 255;
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
}

function luminance([red, green, blue]: [number, number, number]): number {
  return 0.2126 * linear(red) + 0.7152 * linear(green) + 0.0722 * linear(blue);
}

function contrast(a: [number, number, number], b: [number, number, number]): number {
  const [high, low] = [luminance(a), luminance(b)].sort((left, right) => right - left);
  return (high + 0.05) / (low + 0.05);
}

function hex(value: string): [number, number, number] {
  const match = /^#([0-9a-f]{6})$/i.exec(value);
  expect(match, `not a hex colour: ${value}`).not.toBeNull();
  const parsed = Number.parseInt(match![1], 16);
  return [(parsed >> 16) & 0xff, (parsed >> 8) & 0xff, parsed & 0xff];
}

describe('UI chrome CSS contract (UI-01)', () => {
  it('renders every frame with the 9-slice kit', () => {
    expect(rule('.aoe-panel')).toContain("url('/assets/ui/panel_frame.png?v=1')");
    expect(rule('.aoe-panel')).toContain("url('/assets/ui/panel_fill.png?v=1')");
    expect(rule('.aoe-frame')).toContain("url('/assets/ui/panel_frame.png?v=1')");
    expect(rule('.aoe-frame-sm')).toContain("url('/assets/ui/tooltip_frame.png?v=1')");
    expect(rule('.aoe-modal')).toContain("url('/assets/ui/modal_frame.png?v=1')");
    expect(rule('.aoe-modal')).toContain("url('/assets/ui/modal_fill.png?v=1')");
    expect(rule('.aoe-tooltip')).toContain("url('/assets/ui/tooltip_frame.png?v=1')");
    expect(rule('.aoe-chip')).toContain("url('/assets/ui/chip_frame.png?v=1')");
    expect(rule('.aoe-button')).toContain("url('/assets/ui/button_idle.png?v=1')");
    expect(rule('.aoe-button')).toContain("url('/assets/ui/button_fill.png?v=1')");
    expect(rule('.aoe-slot')).toContain("url('/assets/ui/slot_idle.png?v=1')");
    expect(rule('.aoe-backdrop')).toContain("url('/assets/ui/backdrop.png?v=1')");
  });

  it('replaces the old flat gradients instead of layering on top of them', () => {
    expect(rule('.aoe-panel')).not.toContain('gradient');
    expect(rule('.aoe-button')).not.toContain('gradient');
    expect(rule('.aoe-panel-inset')).not.toContain('linear-gradient');
  });

  it('keeps border-width unchanged so the 156 px dock does not move', () => {
    // The ring is painted inward by border-image-width, which is larger than
    // border-width; `dockMetrics.ts` and `DockBar.test.tsx` depend on this.
    expect(rule('.aoe-panel')).toMatch(/border:\s*2px solid/);
    expect(rule('.aoe-panel')).toMatch(/border-image:.*\/\s*8px/);
    expect(rule('.aoe-button')).toMatch(/border:\s*1px solid/);
    expect(rule('.aoe-button')).toMatch(/border-image:.*\/\s*3px/);
    expect(rule('.aoe-slot')).toMatch(/border:\s*1px solid/);
    expect(rule('.aoe-slot')).toMatch(/border-image:.*\/\s*4px/);
  });

  it('swaps the button and slot state images', () => {
    expect(rule('.aoe-button:hover:not(:disabled)')).toContain('button_hover.png');
    expect(rule('.aoe-button:active:not(:disabled)')).toContain('button_pressed.png');
    expect(rule('.aoe-button:disabled')).toContain('button_disabled.png');
    expect(rule(".aoe-button[aria-pressed='true']:not(:disabled)")).toContain('button_active.png');
    expect(rule('.aoe-slot:hover:not(:disabled)')).toContain('slot_hover.png');
    expect(rule(".aoe-slot[aria-pressed='true']:not(:disabled)")).toContain('slot_active.png');
    expect(rule('.aoe-slot:disabled')).toContain('slot_disabled.png');
    expect(rule('.aoe-button.aoe-button-danger:not(:disabled)')).toContain('button_danger_idle.png');
    expect(rule('.aoe-button.aoe-button-primary:not(:disabled)')).toContain('button_primary_idle.png');
    expect(rule('.aoe-button.aoe-button-primary:not(:disabled)')).toContain('primary_fill.png');
  });
});

describe('UI chrome asset files (UI-01)', () => {
  it('ships exactly the assets the lock records and the CSS references', () => {
    const locked = Object.keys(LOCK.assets).sort();
    const referenced = Array.from(
      new Set(
        Array.from(CSS.matchAll(/\/assets\/ui\/([a-z0-9_]+)\.png/g)).map((match) => match[1])
      )
    ).sort();

    expect(referenced).toEqual(locked);
    for (const name of locked) {
      expect(existsSync(resolve(UI_DIR, `${name}.png`)), `${name}.png`).toBe(true);
    }
  });

  it('uses one cache-busting version for the whole kit', () => {
    const versions = Array.from(
      new Set(
        Array.from(CSS.matchAll(/\/assets\/ui\/[a-z0-9_]+\.png\?v=(\d+)/g)).map((match) =>
          Number(match[1])
        )
      )
    );

    expect(versions).toEqual([LOCK.version]);
  });

  it('ships valid PNGs at the recorded dimensions', () => {
    for (const [name, entry] of Object.entries(LOCK.assets)) {
      const size = pngSize(resolve(UI_DIR, entry.file));
      expect(size, name).toEqual({ width: entry.width, height: entry.height });
    }
  });

  it('keeps every frame ring opaque and every edge strip uniform', () => {
    for (const [name, entry] of Object.entries(LOCK.assets)) {
      if (!('slice' in entry)) continue;
      expect(entry.ringMinAlpha, `${name} ring alpha`).toBeGreaterThanOrEqual(250);
      expect(entry.edgeStdMax, `${name} edge std`).toBeLessThanOrEqual(2);
      expect(entry.slice, `${name} slice`).toBeLessThan(Math.min(entry.width, entry.height) / 2);
      expect(entry.borderWidthPx, `${name} border width`).toBeGreaterThanOrEqual(3);
    }
  });

  it('keeps every fill tile seam-free enough to repeat', () => {
    for (const [name, entry] of Object.entries(LOCK.assets)) {
      if (!('tile' in entry)) continue;
      expect(entry.tile, name).toBe(true);
      expect(entry.edgeDiff, `${name} edge diff`).toBeLessThanOrEqual(8);
    }
  });

  it('stays small enough for the public bundle', () => {
    const bytes = Object.values(LOCK.assets).reduce(
      (total, entry) => total + readFileSync(resolve(UI_DIR, entry.file)).byteLength,
      0
    );
    expect(bytes).toBeLessThan(300 * 1024);
  });
});

describe('UI chrome text contrast (UI-01)', () => {
  const SURFACES: Array<{ fill: string; texts: string[]; darkText?: boolean }> = [
    { fill: 'panel_fill', texts: ['#fbbf24', '#e2e8f0', '#94a3b8'] },
    { fill: 'modal_fill', texts: ['#fcd34d', '#e2e8f0', '#94a3b8'] },
    { fill: 'button_fill', texts: ['#e2e8f0', '#fef3c7', '#fecaca'] },
    { fill: 'inset_fill', texts: ['#e2e8f0', '#fbbf24', '#94a3b8'] },
    { fill: 'primary_fill', texts: ['#0f172a'], darkText: true }
  ];

  it('clears 4.5:1 for 11 px text on every fill', () => {
    for (const surface of SURFACES) {
      const entry = LOCK.assets[surface.fill] as FillEntry;
      expect(entry, surface.fill).toBeDefined();
      const fill = surface.darkText ? entry.p1Rgb : entry.p99Rgb;
      for (const text of surface.texts) {
        const ratio = contrast(fill, hex(text));
        expect(
          ratio,
          `${surface.fill} ${surface.darkText ? 'p1' : 'p99'} vs ${text}`
        ).toBeGreaterThanOrEqual(4.5);
      }
    }
  });
});

describe('UI chrome is wired into the chrome surfaces (UI-01)', () => {
  it('uses the new classes on the dock, HUD and overlays', () => {
    expect(source('dock/CommandCard.tsx')).toContain('aoe-slot');
    expect(source('HUD.tsx')).toContain('aoe-panel');
    expect(source('HUD.tsx')).toContain('aoe-chip');
    expect(source('BuildMenu.tsx')).toContain('aoe-tooltip');
    expect(source('AuthScreen.tsx')).toContain('aoe-modal');
    expect(source('SessionBlocked.tsx')).toContain('aoe-modal');
    expect(source('WorldMapOverlay.tsx')).toContain('aoe-backdrop');
    expect(source('PlacementBanner.tsx')).toContain('aoe-frame-sm');
    expect(
      readFileSync(resolve(COMPONENT_DIR, '../game/alerts/rejectVisuals.ts'), 'utf8')
    ).toContain('aoe-frame-sm');
  });
});
